with flagged as (select *, case when lag(event_time) over (partition by session_id order by event_time, id) is null or event_time > lag(event_time) over (partition by session_id order by event_time, id) + interval 30 days then 1 else 0 end as session_start_flag from web_events) select id, session_id, page, event_time, sum(session_start_flag) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as session_id_2 from flagged;
